import copy
import json
import subprocess
import sys

sys.path.insert(0, '/workspace/submission')

BASE = {
    'cases': [{
        'nodes': 4,
        'edges': [[0, 1, 5], [1, 2, 4], [2, 3, 3], [0, 3, 2], [3, 0, 1]],
        'commodities': [
            {'source': 0, 'sink': 3, 'demand': 4, 'paths': [[0, 1, 2], [3]]},
            {'source': 3, 'sink': 1, 'demand': 2, 'paths': [[4, 0], None]},
        ],
        'workers': [[0], [1]],
        'quorum': 1,
        'max_lag': 2,
        'relax': [3, 2],
        'rho': 2,
        'mode': 'route',
        'events': [
            {'op': 'configure', 'mode': 'admit', 'capacity': [[1, 0]], 'demand': [[0, 5]],
             'paths': [[1, 1, [4, 0, 1, 2]]]},
            {'op': 'issue', 'id': 7, 'worker': 0},
            {'op': 'issue', 'id': 8, 'worker': 1},
            {'op': 'deliver', 'id': 7},
            {'op': 'deliver', 'id': 8},
            {'op': 'step'},
            {'op': 'retune', 'rho': 5},
            {'op': 'save', 'name': 1},
            {'op': 'audit'},
            {'op': 'restore', 'name': 1},
            {'op': 'deliver', 'id': 7},
            {'op': 'step'},
            {'op': 'audit'},
        ],
    }]
}


def mutate(fn):
    case = copy.deepcopy(BASE)
    fn(case)
    return case


def run(raw):
    if isinstance(raw, str):
        raw = raw.encode('utf-8')
    proc = subprocess.run([sys.executable, '-B', 'submission/main.py'], input=raw,
                          capture_output=True)
    return proc


def check(name, raw, expect_error=True):
    proc = run(raw)
    out = proc.stdout.decode('utf-8').strip()
    ok = proc.returncode == 0
    try:
        parsed = json.loads(out)
    except Exception:
        parsed = None
    if expect_error:
        good = ok and parsed == {'error': 'invalid_request'}
    else:
        good = ok and isinstance(parsed, dict) and 'cases' in parsed and len(parsed['cases']) > 0
    if not good:
        print('FAIL', name, 'rc=', proc.returncode, 'out=', out[:200], 'err=',
              proc.stderr.decode()[:400])
        return 1
    return 0


