    cases.append(('trailing', b'{"cases":[]}{}'))
    cases.append(('trailing-comma', b'{"cases":[],}'))
    cases.append(('bom', b'\xef\xbb\xbf{"cases":[]}'))
    cases.append(('non-utf8', b'{"cases": [], "x": "\xff\xfe"}'))
    cases.append(('nan', b'{"cases":[],"z":NaN}'))
    cases.append(('inf', b'{"cases":[],"z":Infinity}'))
    cases.append(('root-array', b'[]'))
    cases.append(('root-number', b'5'))
    cases.append(('root-string', b'"x"'))
    cases.append(('null-root', b'null'))
    cases.append(('dup-root-key', b'{"cases":[],"cases":[]}'))
    cases.append(('dup-nested-key', b'{"cases":[{"nodes":2,"nodes":3}]}'))
    cases.append(('unknown-root-key', b'{"cases":[],"extra":1}'))
    s = json.dumps(BASE)
    cases.append(('float-node', s.replace('"nodes": 4', '"nodes": 4.0')))
    cases.append(('bool-node', s.replace('"nodes": 4', '"nodes": true')))
    cases.append(('string-cap', s.replace('[0, 1, 5]', '[0, 1, "5"]')))

    def m_unknown_case_key(c):
        c['cases'][0]['extra'] = 1

    def m_missing_case_key(c):
        del c['cases'][0]['rho']

    def m_nodes_range(c):
        c['cases'][0]['nodes'] = 1

    def m_nodes_range2(c):
