    def m_dup_edge(c):
        c['cases'][0]['edges'][1] = [0, 1, 3]

    def m_rev_edge_ok(c):
        # reverse direction is legal -> not an error case
        pass

    def m_cap_range(c):
        c['cases'][0]['edges'][0][2] = 1001

