    def m_event_missing_key(c):
        c['cases'][0]['events'][1] = {'op': 'issue', 'id': 7}

    def m_dup_ticket(c):
        c['cases'][0]['events'][2] = {'op': 'issue', 'id': 7, 'worker': 1}

    def m_ticket_range(c):
        c['cases'][0]['events'][1]['id'] = 10**9 + 1

    def m_ticket_float(c):
