    def m_deliver_unknown(c):
        c['cases'][0]['events'][3] = {'op': 'deliver', 'id': 99}

    def m_deliver_future(c):
        ev = c['cases'][0]['events']
        ev[3] = {'op': 'deliver', 'id': 8}
        del ev[2]

    def m_worker_range(c):
        c['cases'][0]['events'][1]['worker'] = 2

    def m_retune_range(c):
