    for fn in [m_unknown_case_key, m_missing_case_key, m_nodes_range, m_nodes_range2, m_no_edges,
               m_selfloop, m_dup_edge, m_cap_range, m_cap_neg, m_edge_shape, m_bad_node_id,
               m_src_eq_sink, m_demand_range, m_bad_com_key, m_too_many_slots, m_slot_total,
