    for name, raw in cases:
        bad += check(name, raw, expect_error=True)
    for name, raw in legal:
        bad += check(name, raw, expect_error=False)
    print('invalid battery failures:', bad)
    return bad


if __name__ == '__main__':
    sys.exit(1 if main() else 0)
